// Plain Kotlin/JVM: the wire protocol, the API's operations and models (generated by Apollo
// from SovEmu's schema), sign-in (OAuth tokens), and the logic over them, testable without
// Android.
plugins {
    alias(libs.plugins.kotlin.jvm)
    alias(libs.plugins.apollo)
}

kotlin {
    jvmToolchain(21)
}

apollo {
    service("sovemu") {
        packageName.set("media.sovereign.sovemu.core.graphql")
        // The schema is SovEmu.Server's schema.graphql, copied here (this repository builds on
        // its own); `./gradlew :core:syncSchema` refreshes it from a SovEmu checkout.
        schemaFiles.from(file("src/main/graphql/schema.graphqls"))
        srcDir("src/main/graphql")
        // Fields the schema marks optional stay nullable; everything is generated as Kotlin.
        generateKotlinModels.set(true)
    }
}

/** Copies the server's schema (when this is checked out inside SovEmu, as a submodule). */
tasks.register<Copy>("syncSchema") {
    description = "Copies SovEmu.Server/schema.graphql from the enclosing SovEmu checkout."
    from(rootProject.file("../SovEmu.Backend/SovEmu.Server/schema.graphql"))
    into("src/main/graphql")
    rename { "schema.graphqls" }
}

dependencies {
    api(libs.apollo.api)
    // The OAuth token client (`Auth.kt`): plain HTTP form posts, outside Apollo.
    api(libs.okhttp)
    api(libs.kotlinx.coroutines.core)
    testImplementation(libs.junit)
    testImplementation(libs.okhttp.mockwebserver)
}
